using Radix.Core.Model;
using Radix.Core.Signals;

namespace Radix.StdLib;

/// <summary>A complete example project ready to serialize or open in the editor.</summary>
public sealed record ExampleProject(string FileName, string DisplayName, string Description, CircuitProject Project);

/// <summary>Ready-made projects shipped with RADIX and generated by the CLI.</summary>
public static class ExampleProjects
{
    public const string DFlipFlopFile = "dff-demo.radix";
    public const string FullAdderFile = "full-adder.radix";
    public const string CounterFile = "binary-counter.radix";
    public const string BalancedTernaryFile = "balanced-ternary-half-adder.radix";

    public static IReadOnlyList<ExampleProject> All() =>
    [
        new(DFlipFlopFile, "D flip-flop", "A hierarchical D flip-flop built from NAND gates. Toggle D and CLK.", CreateDFlipFlopDemo()),
        new(FullAdderFile, "Full adder", "A full adder built from two half adders and an OR gate.", CreateFullAdderDemo()),
        new(CounterFile, "4-bit counter", "A free-running 4-bit binary counter: DFFs, a ripple-carry adder, and a waveform clock.", CreateCounterDemo()),
        new(BalancedTernaryFile, "Balanced ternary half adder", "Two-trit addition with sum and carry on a three-valued domain.", CreateBalancedTernaryHalfAdderDemo()),
    ];

    public static CircuitProject CreateDFlipFlopDemo()
    {
        var builder = new ProjectBuilder("D flip-flop demo");
        StandardLibrary.Install(builder.Project);
        var root = builder.Define("demo.dff", "D flip-flop demo");
        root.Definition.Description = "Top-level wrapper around std.dff with interactive D and CLK inputs.";

        Net d = root.AddPin("d", "D", PinDirection.Input, StandardDomains.BinaryId);
        Net clk = root.AddPin("clk", "CLK", PinDirection.Input, StandardDomains.BinaryId);
        Net q = root.SetInitial(root.AddPin("q", "Q", PinDirection.Output, StandardDomains.BinaryId), 0);
        Net qn = root.SetInitial(root.AddPin("qn", "QN", PinDirection.Output, StandardDomains.BinaryId), 1);

        root.AddInstance("ff", StandardLibrary.DFlipFlopId, 220, 100);
        root.Connect(d, root.Pin("ff", "d"));
        root.Connect(clk, root.Pin("ff", "clk"));
        root.Connect(q, root.Pin("ff", "q"));
        root.Connect(qn, root.Pin("ff", "qn"));

        return builder.Build("demo.dff");
    }

    public static CircuitProject CreateFullAdderDemo()
    {
        var builder = new ProjectBuilder("Full adder demo");
        StandardLibrary.Install(builder.Project);
        var root = builder.Define("demo.full-adder", "Full adder demo");

        Net a = root.AddPin("a", "A", PinDirection.Input, StandardDomains.BinaryId);
        Net b = root.AddPin("b", "B", PinDirection.Input, StandardDomains.BinaryId);
        Net cin = root.AddPin("cin", "CIN", PinDirection.Input, StandardDomains.BinaryId);
        Net s = root.AddPin("s", "S", PinDirection.Output, StandardDomains.BinaryId);
        Net cout = root.AddPin("cout", "COUT", PinDirection.Output, StandardDomains.BinaryId);

        root.AddInstance("adder", "std.full-adder", 220, 100);
        root.Connect(a, root.Pin("adder", "a"));
        root.Connect(b, root.Pin("adder", "b"));
        root.Connect(cin, root.Pin("adder", "cin"));
        root.Connect(s, root.Pin("adder", "s"));
        root.Connect(cout, root.Pin("adder", "cout"));

        return builder.Build("demo.full-adder");
    }

    public static CircuitProject CreateCounterDemo()
    {
        var builder = new ProjectBuilder("4-bit binary counter");
        StandardLibrary.Install(builder.Project);
        var root = builder.Define("demo.counter", "4-bit binary counter");
        root.Definition.Description =
            "Free-running 4-bit counter. A waveform clock drives four DFFs whose next state is Q+1 from a ripple-carry adder.";

        var qNets = new Net[4];
        for (int i = 0; i < 4; i++)
        {
            qNets[i] = root.SetInitial(
                root.AddPin($"q{i}", $"Q{i}", PinDirection.Output, StandardDomains.BinaryId),
                0);
        }

        Net clock = root.AddNet("clk", StandardDomains.BinaryId);
        // A 20-tick clock leaves ample time for the ripple-carry next state to
        // settle before the flip-flop capture window.
        root.AddPrimitive("clock", new WaveformSpec([10, 10], [0, 1]), 60, 400);
        root.Connect(clock, root.Pin("clock", "out"));

        var bNets = new Net[4];
        for (int i = 0; i < 4; i++)
        {
            bNets[i] = root.AddNet($"b{i}", StandardDomains.BinaryId);
            root.AddPrimitive($"const_b{i}", new ConstantSpec(i == 0 ? 1 : 0), 60, 60 + (i * 40));
            root.Connect(bNets[i], root.Pin($"const_b{i}", "out"));
        }

        var sumNets = new Net[4];
        for (int i = 0; i < 4; i++)
        {
            sumNets[i] = root.AddNet($"sum{i}", StandardDomains.BinaryId);
        }

        root.AddInstance("adder", "std.ripple-adder-4", 280, 120);
        for (int i = 0; i < 4; i++)
        {
            root.Connect(qNets[i], root.Pin("adder", $"a{i}"));
            root.Connect(bNets[i], root.Pin("adder", $"b{i}"));
            root.Connect(sumNets[i], root.Pin("adder", $"s{i}"));
        }

        for (int i = 0; i < 4; i++)
        {
            root.AddInstance($"ff{i}", StandardLibrary.DFlipFlopId, 560, 60 + (i * 100));
            root.Connect(sumNets[i], root.Pin($"ff{i}", "d"));
            root.Connect(clock, root.Pin($"ff{i}", "clk"));
            root.Connect(qNets[i], root.Pin($"ff{i}", "q"));
        }

        return builder.Build("demo.counter");
    }

    public static CircuitProject CreateBalancedTernaryHalfAdderDemo()
    {
        var builder = new ProjectBuilder("Balanced ternary half adder");
        StandardLibrary.Install(builder.Project);
        var root = builder.Define("demo.bt-half-adder", "Balanced ternary half adder");

        Net a = root.AddPin("a", "A", PinDirection.Input, StandardDomains.BalancedTernaryId);
        Net b = root.AddPin("b", "B", PinDirection.Input, StandardDomains.BalancedTernaryId);
        Net s = root.AddPin("s", "S", PinDirection.Output, StandardDomains.BalancedTernaryId);
        Net c = root.AddPin("c", "C", PinDirection.Output, StandardDomains.BalancedTernaryId);

        root.AddInstance("adder", "std.bt-half-adder", 220, 100);
        root.Connect(a, root.Pin("adder", "a"));
        root.Connect(b, root.Pin("adder", "b"));
        root.Connect(s, root.Pin("adder", "s"));
        root.Connect(c, root.Pin("adder", "c"));

        return builder.Build("demo.bt-half-adder");
    }
}
